rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe')
 for name,run in {'profile-dirty-draft-router':profile_drafts,'tag-rename-create-delete':tags,'privacy-default-notification-gate':privacy_notifications,'export-common-backup-cache':export_backup,'pair-request-confirm-logout':pair_logout}.items():
  c=b.new_context(viewport={'width':390,'height':844},accept_downloads=True);p=c.new_page();p.set_default_timeout(4000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
  try:run(p);assert not errors,errors;row={'case':name,'passed':True}
  except Exception as e:row={'case':name,'passed':False,'failure':repr(e)[:1600]}
  row.update(errors=errors,final_url=p.url);rows.append(row);(OUT/'settings-flow-results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8');p.screenshot(path=str(OUT/f'settings-{name}.png'),full_page=True);print(('PASS ' if row['passed'] else 'FAIL ')+name,flush=True);c.close()
 b.close()
raise SystemExit(0 if all(r['passed'] for r in rows) else 1)
